create table public.marketplace_categories(id uuid primary key default gen_random_uuid(),parent_id uuid references public.marketplace_categories(id) on delete restrict,slug citext not null unique,name text not null,is_active boolean not null default true,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()));
create table public.marketplace_products(id uuid primary key default gen_random_uuid(),seller_id uuid not null references public.profiles(id) on delete restrict,campus_id uuid not null references public.campuses(id) on delete restrict,category_id uuid references public.marketplace_categories(id) on delete set null,title text not null,description text not null default '',condition text not null,price numeric(14,2) not null,currency char(3) not null default 'INR',status text not null default 'draft',created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),deleted_at timestamptz,search_document tsvector generated always as(to_tsvector('simple',title||' '||description)) stored,constraint product_price check(price>=0),constraint product_status check(status in('draft','active','reserved','sold','hidden','removed')));
create table public.product_media(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.marketplace_products(id) on delete cascade,media_asset_id uuid not null references public.media_assets(id) on delete restrict,position smallint not null,created_at timestamptz not null default timezone('utc',now()),unique(product_id,position),unique(product_id,media_asset_id));
create table public.product_favorites(product_id uuid not null references public.marketplace_products(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default timezone('utc',now()),primary key(product_id,user_id));
create table public.product_reports(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.marketplace_products(id) on delete restrict,reporter_id uuid not null references public.profiles(id) on delete restrict,reason text not null,status text not null default 'open',created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),unique(product_id,reporter_id,reason),constraint product_report_status check(status in('open','reviewed','dismissed','actioned')));
create index marketplace_products_feed_idx on public.marketplace_products(campus_id,status,created_at desc) where deleted_at is null; create index marketplace_products_category_idx on public.marketplace_products(category_id,status,created_at desc) where deleted_at is null; create index marketplace_products_seller_idx on public.marketplace_products(seller_id,status); create index marketplace_products_search_idx on public.marketplace_products using gin(search_document); create index product_media_asset_idx on public.product_media(media_asset_id); create index product_reports_queue_idx on public.product_reports(status,created_at);
create trigger marketplace_categories_updated before update on public.marketplace_categories for each row execute function public.set_updated_at(); create trigger marketplace_products_updated before update on public.marketplace_products for each row execute function public.set_updated_at(); create trigger product_reports_updated before update on public.product_reports for each row execute function public.set_updated_at();
alter table public.marketplace_categories enable row level security; alter table public.marketplace_products enable row level security; alter table public.product_media enable row level security; alter table public.product_favorites enable row level security; alter table public.product_reports enable row level security;
create policy marketplace_categories_read on public.marketplace_categories for select to authenticated using(is_active); create policy marketplace_categories_manage on public.marketplace_categories for all to authenticated using(public.has_permission('marketplace.categories.manage')) with check(public.has_permission('marketplace.categories.manage'));
create policy products_read on public.marketplace_products for select to authenticated using((status='active' and deleted_at is null) or seller_id=auth.uid() or public.has_permission('marketplace.moderate',campus_id)); create policy products_insert on public.marketplace_products for insert to authenticated with check(seller_id=auth.uid() and public.has_permission('marketplace.create',campus_id)); create policy products_update on public.marketplace_products for update to authenticated using(seller_id=auth.uid() or public.has_permission('marketplace.moderate',campus_id)) with check(seller_id=auth.uid() or public.has_permission('marketplace.moderate',campus_id)); create policy products_delete on public.marketplace_products for delete to authenticated using(public.has_permission('marketplace.moderate',campus_id));
create policy product_media_read on public.product_media for select to authenticated using(exists(select 1 from public.marketplace_products p where p.id=product_id and ((p.status='active' and p.deleted_at is null) or p.seller_id=auth.uid()))); create policy product_media_owner on public.product_media for all to authenticated using(exists(select 1 from public.marketplace_products p where p.id=product_id and p.seller_id=auth.uid())) with check(exists(select 1 from public.marketplace_products p where p.id=product_id and p.seller_id=auth.uid())); create policy product_favorites_owner on public.product_favorites for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy product_reports_read on public.product_reports for select to authenticated using(reporter_id=auth.uid() or public.has_permission('marketplace.moderate')); create policy product_reports_insert on public.product_reports for insert to authenticated with check(reporter_id=auth.uid()); create policy product_reports_update on public.product_reports for update to authenticated using(public.has_permission('marketplace.moderate')) with check(public.has_permission('marketplace.moderate'));
